function flexi_sync_applicant_name(frm) {
    const full_name = [
        frm.doc.custom_first_name,
        frm.doc.custom_middle_name,
        frm.doc.custom_surname
    ].filter(Boolean).map(value => String(value).trim()).filter(Boolean).join(' ');
    if (frm.doc.applicant_name !== full_name) frm.set_value('applicant_name', full_name);
    if (full_name && frm.doc.custom_cira_authority_name !== full_name) {
        frm.set_value('custom_cira_authority_name', full_name);
    }
}

async function flexi_prefill_customer(frm) {
    if (frm.doc.applicant_type !== 'Customer' || !frm.doc.applicant) return;
    const customer = await frappe.db.get_doc('Customer', frm.doc.applicant);
    let contact = null;
    let address = null;
    if (customer.customer_primary_contact) {
        try { contact = await frappe.db.get_doc('Contact', customer.customer_primary_contact); } catch (error) {}
    }
    if (customer.customer_primary_address) {
        try { address = await frappe.db.get_doc('Address', customer.customer_primary_address); } catch (error) {}
    }
    const contactHasSplitName = Boolean(contact?.middle_name || contact?.last_name);
    const fullName = contact?.full_name || customer.customer_name || '';
    const parts = String(fullName).trim().split(/\s+/).filter(Boolean);
    const values = {
        custom_customer_full_name: customer.customer_name || fullName,
        custom_first_name: contactHasSplitName ? (contact?.first_name || '') : (parts[0] || ''),
        custom_middle_name: contactHasSplitName ? (contact?.middle_name || '') : (parts.length > 2 ? parts.slice(1, -1).join(' ') : ''),
        custom_surname: contactHasSplitName ? (contact?.last_name || '') : (parts.length > 1 ? parts[parts.length - 1] : ''),
        custom_tin_number: customer.custom_tin_number || '',
        applicant_email_address: customer.email_id || contact?.email_ids?.find(row => row.is_primary)?.email_id || '',
        applicant_phone_number: customer.mobile_no || contact?.phone_nos?.find(row => row.is_primary_mobile_no)?.phone || '',
        address_line_1: address?.address_line1 || '',
        address_line_2: address?.address_line2 || '',
        custom_new_city: address?.city || '',
        city: address?.city || '',
        custom_province: address?.state || '',
        state: address?.state || '',
        country: address?.country || 'Fiji',
        zip_code: address?.pincode || ''
    };
    await frm.set_value(values);
    flexi_sync_applicant_name(frm);
}

