function updateFlexiEmploymentPeriod(frm) {
    const value = frm.doc.custom_flexi_employment_start_date;
    let result = "";

    if (value) {
        const start = frappe.datetime.str_to_obj(value);
        const today = frappe.datetime.str_to_obj(
            frappe.datetime.get_today()
        );

        if (!(start instanceof Date) ||
            Number.isNaN(start.getTime())) return;

        start.setHours(0, 0, 0, 0);
        today.setHours(0, 0, 0, 0);

        if (start > today) {
            result = "Invalid - future date";
        } else {
            let months =
                (today.getFullYear() - start.getFullYear()) * 12
                + today.getMonth() - start.getMonth();

            if (today.getDate() < start.getDate()) months--;

            months = Math.max(0, months);

            const years = Math.floor(months / 12);
            const remainingMonths = months % 12;
            const parts = [];

            if (years) {
                parts.push(
                    years + (years === 1 ? " year" : " years")
                );
            }

            if (remainingMonths) {
                parts.push(
                    remainingMonths
                    + (remainingMonths === 1 ? " month" : " months")
                );
            }

            result = parts.join(", ") || "Less than 1 month";
        }
    } else {
        // Preserve existing manually entered periods on older records.
        // Clear only when the start date is removed by the user.
        if (!frm.is_dirty()) return;
    }

    if ((frm.doc.custom_flexi_employment_period || "") !== result) {
        return frm.set_value(
            "custom_flexi_employment_period",
            result
        );
    }
}

