const flexi_monthly_factor = (frequency) => ({
    "Weekly": 52 / 12,
    "Fortnightly": 26 / 12,
    "Bi-monthly": 2,
    "Monthly": 1
}[frequency] || 1);

const flexi_round = (value) => Math.round((flt(value) + Number.EPSILON) * 100) / 100;
let flexi_syncing_deposit = false;

function flexi_set_child_monthly(cdt, cdn) {
    const row = locals[cdt][cdn];
    frappe.model.set_value(cdt, cdn, "monthly_amount", flexi_round(flt(row.amount) * flexi_monthly_factor(row.frequency)));
}

function flexi_calculate_age(frm) {
    if (!frm.doc.custom_flexi_date_of_birth) {
        frm.set_value("custom_flexi_age", 0);
        return;
    }
    const birth = frappe.datetime.str_to_obj(frm.doc.custom_flexi_date_of_birth);
    const today = frappe.datetime.str_to_obj(frappe.datetime.get_today());
    let age = today.getFullYear() - birth.getFullYear();
    if (today.getMonth() < birth.getMonth() ||
        (today.getMonth() === birth.getMonth() && today.getDate() < birth.getDate())) age -= 1;
    frm.set_value("custom_flexi_age", Math.max(age, 0));
}

function flexi_calculate(frm, source = "amount") {
    if (frm.doctype !== "Loan Application" || frm.doc.docstatus !== 0) return;
    const values = window.comfort_hp_math.evaluate(frm.doc, source);
    const weeklyCount = values.custom_flexi_weekly_instalments;
    const fortnightlyCount = values.custom_flexi_fortnightly_instalments;
    const bimonthlyCount = values.custom_flexi_bimonthly_instalments;
    const monthlyCount = values.custom_flexi_monthly_instalments;
    flexi_syncing_deposit = true;
    Object.entries(values).forEach(([key, value]) => {
        if (frm.fields_dict[key] && frm.doc[key] !== value) frm.set_value(key, value);
    });
    window.setTimeout(() => { flexi_syncing_deposit = false; }, 100);

    if (frm.doc.custom_flexi_first_instalment_date) {
        let lastDate = frm.doc.custom_flexi_first_instalment_date;
        const period = frm.doc.custom_flexi_payment_period;
        if (period === "Weekly" && weeklyCount > 1) {
            lastDate = frappe.datetime.add_days(lastDate, (weeklyCount - 1) * 7);
        } else if (period === "Fortnightly" && fortnightlyCount > 1) {
            lastDate = frappe.datetime.add_days(lastDate, (fortnightlyCount - 1) * 14);
        } else if (period === "Bi-monthly" && bimonthlyCount > 1) {
            lastDate = frappe.datetime.add_days(lastDate, Math.round((bimonthlyCount - 1) * 365.25 / 24));
        } else if (monthlyCount > 1) {
            lastDate = frappe.datetime.add_months(lastDate, monthlyCount - 1);
        }
        frm.set_value("custom_flexi_last_instalment_date", lastDate);
    }
    flexi_calculate_age(frm);
}

function flexi_sync_standard_address(frm) {
    const city = frm.doc.custom_new_city || "";
    const province = frm.doc.custom_province || "";
    if (frm.doc.city !== city) frm.set_value("city", city);
    if (frm.doc.state !== province) frm.set_value("state", province);
}

